using Xunit;
using static Wizard.Analyzers.Tests.AnalyzerHarness;

namespace Wizard.Analyzers.Tests
{
    // 분석기는 생성 코드도 검사한다(ConfigureGeneratedCodeAnalysis(Analyze | ReportDiagnostics), T-42).
    // 파일 이름(*.g.cs), <auto-generated> 머리말, [GeneratedCode] 특성으로 금지 목록을 피할 수 없다.
    public sealed class GeneratedCodeTests
    {
        [Fact]
        public void GeneratedFileNameDoesNotEscape()
        {
            const string code = "namespace Wizard.Core { public static class X { public static double F() => 1.5; } }";
            Assert.Contains("WZ0001", Ids("Wizard.Core", code, "/repo/src/Wizard.Core/Generated/X.g.cs"));
            Assert.Contains("WZ0001", Ids("Wizard.Core", code, "/repo/src/Wizard.Core/X.designer.cs"));
            Assert.Contains("WZ0001", Ids("Wizard.Core", code, "/repo/src/Wizard.Core/X.generated.cs"));
        }

        [Fact]
        public void AutoGeneratedHeaderDoesNotEscape()
        {
            const string code = "// <auto-generated/>\nnamespace Wizard.Sim { public static class X { public static int F() => new System.Random(1).Next(); } }";
            Assert.Contains("WZ0002", Ids("Wizard.Sim", code, "/repo/src/Wizard.Sim/X.cs"));
            const string header = "// <auto-generated>\n// tool output\n// </auto-generated>\nnamespace Wizard.Core { static class X { static int s_hits; } }";
            Assert.Contains("WZ0010", Ids("Wizard.Core", header, "/repo/src/Wizard.Core/Generated/SinTable.g.cs"));
        }

        [Fact]
        public void GeneratedCodeAttributeDoesNotEscape()
        {
            const string code = "namespace Wizard.Content { [System.CodeDom.Compiler.GeneratedCode(\"tool\", \"1\")] public static class X { " +
                                "public static int F(int a, int b) => a / b; } }";
            Assert.Contains("WZ0014", Ids("Wizard.Content", code, "/repo/src/Wizard.Content/X.cs"));
        }

        [Fact]
        public void GeneratedCodeIsCheckedForSuppression()
        {
            const string code = "// <auto-generated/>\n#pragma warning disable WZ0001\nnamespace Wizard.Core { static class X { static double D; } }";
            Assert.Contains("WZ0016", Ids("Wizard.Core", code, "/repo/src/Wizard.Core/Generated/X.g.cs"));
        }

        [Fact]
        public void HandWrittenCodeWithoutViolationsIsClean()
        {
            const string code = "// <auto-generated/>\nnamespace Wizard.Core { internal static class SinTable { internal static readonly long[] Raw = { 0L }; } }";
            Assert.Empty(Ids("Wizard.Core", code, "/repo/src/Wizard.Core/Generated/SinTable.g.cs"));
        }
    }
}
